const norm = s => (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
const file = $input.first().json;
const datos = JSON.parse(Buffer.from(file.content, 'base64').toString('utf8'));

const dominios = [], nombres = [];
for (const o of datos.orgs) {
  (o.domains || []).forEach(d => dominios.push(norm(d)));
  nombres.push(norm(o.name.split('—')[0]));
}
return [{ json: { dominiosConocidos: dominios, nombresConocidos: nombres } }];

const norm = s => (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
const limpioDominio = d => norm(d).replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '');

const oficiales = $('Extraer dominios oficiales conocidos').first().json;
const file = $input.first().json;
const pend = JSON.parse(Buffer.from(file.content, 'base64').toString('utf8'));
const actuales = pend.candidatas || [];

const dominiosEnCola = actuales.map(c => limpioDominio(c.dominio)).filter(Boolean);
const nombresEnCola = actuales.map(c => norm(c.nombre)).filter(Boolean);

return [{
  json: {
    dominiosConocidos: [...oficiales.dominiosConocidos, ...dominiosEnCola],
    nombresConocidos: [...oficiales.nombresConocidos, ...nombresEnCola],
    pendientesActuales: actuales,
    pendientesSha: file.sha,
    pendMeta: pend.meta || {},
  }
}];

// Se parsea el XML a mano con regex (sin depender del nodo XML de n8n, cuyo
// formato de salida exacto no se pudo confirmar sin una instancia real). Probado
// contra el RSS real de Google Noticias antes de empacar esto — ver commit.
const conocidosInfo = $('Combinar conocidos y candidatas en cola').first().json;
const xml = $input.first().json.body;

const bloques = [...xml.matchAll(/<item>([\s\S]*?)<\/item>/g)].map(m => m[1]);
const items = bloques.map(b => {
  const titulo = (b.match(/<title>([\s\S]*?)<\/title>/) || [, ''])[1];
  const link = (b.match(/<link>([\s\S]*?)<\/link>/) || [, ''])[1];
  const pubDate = (b.match(/<pubDate>([\s\S]*?)<\/pubDate>/) || [, ''])[1];
  const fuenteMatch = b.match(/<source url="([^"]*)">([\s\S]*?)<\/source>/);
  return {
    tituloArticulo: titulo,
    linkGoogleNews: link,
    fecha: pubDate,
    fuenteNombre: fuenteMatch ? fuenteMatch[2] : null,
    fuenteUrl: fuenteMatch ? fuenteMatch[1] : null,
  };
});

// No martillar sitios de prensa ni gastar de más en Claude en una sola corrida
// (CLAUDE.md sección 5: 'no martilles los servidores').
const MAX_POR_CORRIDA = 15;

return items.slice(0, MAX_POR_CORRIDA).map(it => ({
  json: { ...it, dominiosConocidos: conocidosInfo.dominiosConocidos, nombresConocidos: conocidosInfo.nombresConocidos }
}));

const origen = $('Expandir artículos candidatos').item.json;
const resp = $input.item.json;
const ok = !resp.error && resp.statusCode >= 200 && resp.statusCode < 300;
const html = ok ? (typeof resp.body === 'string' ? resp.body : JSON.stringify(resp.body)) : '';
const textoPlano = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

return { json: { ...origen, textoPlano: textoPlano.slice(0, 12000), fetchOk: ok && textoPlano.length > 200 } };

const origen = $('Extraer texto del artículo').item.json;
const respuestaClaude = $input.item.json;
return { json: { ...origen, respuestaClaude } };

// Regla 3 aplicada al descubrimiento: el nombre y el dominio propuestos por
// Claude deben aparecer literalmente en el texto REAL del artículo descargado.
// Si no, se descartan sin más — nunca se pone en cola algo que pudo inventarse.
const norm = s => (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
const limpioDominio = d => norm(d).replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '');

const conocidosInfo = $('Combinar conocidos y candidatas en cola').first().json;
const items = $input.all().map(it => it.json);
const nuevas = [];
const vistasEnEstaCorrida = new Set();

for (const j of items) {
  if (!j.fetchOk) continue;

  let extraidos = [];
  try {
    const resp = j.respuestaClaude;
    const texto = (resp && resp.content && resp.content[0] && resp.content[0].text) || '[]';
    extraidos = JSON.parse(texto);
    if (!Array.isArray(extraidos)) extraidos = [];
  } catch (e) { extraidos = []; }

  for (const c of extraidos) {
    if (!c || !c.nombre) continue;
    const nombreNorm = norm(c.nombre);
    const dominioNorm = c.dominio ? limpioDominio(c.dominio) : null;

    const textoNorm = norm(j.textoPlano);
    const nombreCorrobora = textoNorm.includes(nombreNorm);
    const dominioCorrobora = dominioNorm ? textoNorm.includes(dominioNorm) : true;
    if (!nombreCorrobora || !dominioCorrobora) continue;

    if (dominioNorm && conocidosInfo.dominiosConocidos.includes(dominioNorm)) continue;
    if (!dominioNorm && conocidosInfo.nombresConocidos.includes(nombreNorm)) continue;

    const clave = dominioNorm || nombreNorm;
    if (vistasEnEstaCorrida.has(clave)) continue;
    vistasEnEstaCorrida.add(clave);

    nuevas.push({
      nombre: c.nombre,
      dominio: c.dominio || null,
      estado: 'candidata_sin_revisar',
      detectado_el: new Date().toISOString(),
      fuente: { titulo: j.tituloArticulo, url: j.linkGoogleNews, publicacion: j.fuenteNombre, fecha: j.fecha },
    });
  }
}

return [{ json: { nuevasCandidatas: nuevas, pendientesActuales: conocidosInfo.pendientesActuales, pendientesSha: conocidosInfo.pendientesSha, pendMeta: conocidosInfo.pendMeta } }];

// Regla 4: solo se añade, nunca se borra ni se sobrescribe una candidata existente.
const info = $input.first().json;
const todas = [...info.pendientesActuales, ...info.nuevasCandidatas];

return [{
  json: {
    contenidoNuevo: JSON.stringify({ meta: info.pendMeta, candidatas: todas }, null, 2),
    pendientesSha: info.pendientesSha,
    hayNuevas: info.nuevasCandidatas.length > 0,
    cantidadNuevas: info.nuevasCandidatas.length,
    nombresNuevas: info.nuevasCandidatas.map(c => c.nombre),
  }
}];
